/** Prints the .env.mock content (deterministic synthetic ids). Run: pnpm tsx mock/envgen.ts > .env.mock */
import { ACCOUNT_ID, ACCOUNT_VERSION, LEAGUE_ID, VALUATION_SNAPSHOT_ID } from './research.ts';

process.stdout.write([
  '# Synthetic mock mode (pnpm dev:mock). Generated by mock/envgen.ts; values are deterministic fake ids.',
  'VITE_USE_MOCK=1',
  `VITE_ACCOUNT_ID=${ACCOUNT_ID}`,
  `VITE_ACCOUNT_VERSION=${ACCOUNT_VERSION}`,
  `VITE_VALUATION_SNAPSHOT_ID=${VALUATION_SNAPSHOT_ID}`,
  `VITE_LEAGUE_ID=${LEAGUE_ID}`,
  'VITE_LEAGUE_VERSION=1',
  '',
].join('\n'));
